import{_ as e,c as t,o,a2 as i}from"./chunks/framework.DgH2I27U.js";const m=JSON.parse('{"title":"Git & GitHub - Stratégie de branches","description":"","frontmatter":{"title":"Git & GitHub - Stratégie de branches","lang":"fr"},"headers":[],"relativePath":"fr/recommandations/branching-strategy.md","filePath":"fr/recommandations/branching-strategy.md"}'),r={name:"fr/recommandations/branching-strategy.md"},n=i('<h1 id="git-github-strategie-de-branches" tabindex="-1">Git &amp; GitHub - Stratégie de branches <a class="header-anchor" href="#git-github-strategie-de-branches" aria-label="Permalink to &quot;Git &amp; GitHub - Stratégie de branches&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Git est un système de contrôle de version distribué qui permet de suivre les modifications du code source. GitHub est une plateforme qui facilite la collaboration et l&#39;hébergement des dépôts Git à distance.</p><p>L&#39;adoption d&#39;une stratégie de branches bien définie est essentielle pour une gestion efficace du code source, en particulier dans un environnement collaboratif.</p><h2 id="concepts-de-base-de-git" tabindex="-1">Concepts de base de Git <a class="header-anchor" href="#concepts-de-base-de-git" aria-label="Permalink to &quot;Concepts de base de Git&quot;">​</a></h2><ul><li><strong>Dépôt (Repository)</strong> : Un projet Git contenant l&#39;historique des versions.</li><li><strong>Commit</strong> : Un enregistrement d&#39;une modification avec un message explicatif.</li><li><strong>Branch (Branche)</strong> : Une version parallèle du code permettant de travailler sur différentes fonctionnalités.</li><li><strong>Merge</strong> : Fusionner une branche dans une autre.</li><li><strong>Pull Request (PR)</strong> : Proposition de fusion d&#39;une branche dans une autre sur GitHub.</li></ul><h2 id="strategies-de-branches" tabindex="-1">Stratégies de branches <a class="header-anchor" href="#strategies-de-branches" aria-label="Permalink to &quot;Stratégies de branches&quot;">​</a></h2><p>Il existe plusieurs stratégies de gestion des branches. Voici les plus courantes :</p><h3 id="_1-git-flow" tabindex="-1">1. Git Flow <a class="header-anchor" href="#_1-git-flow" aria-label="Permalink to &quot;1. Git Flow&quot;">​</a></h3><p>Git Flow est une stratégie qui sépare le développement en plusieurs branches principales :</p><ul><li><code>main</code> : Contient le code stable et en production.</li><li><code>develop</code> : Contient le code en développement avant sa stabilisation.</li><li><code>feature/*</code> : Branches utilisées pour le développement de nouvelles fonctionnalités.</li><li><code>release/*</code> : Préparation d&#39;une nouvelle version stable.</li><li><code>hotfix/*</code> : Corrections urgentes appliquées directement à <code>main</code>.</li></ul><p><strong>Workflow typique :</strong></p><ol><li>Création d&#39;une branche <code>feature/nom-feature</code> à partir de <code>develop</code>.</li><li>Développement et commits sur cette branche.</li><li>Fusion de la branche <code>feature/nom-feature</code> dans <code>develop</code>.</li><li>Lorsqu&#39;une version est prête, une branche <code>release/x.y.z</code> est créée à partir de <code>develop</code>.</li><li>Après tests et corrections, la branche <code>release/x.y.z</code> est fusionnée dans <code>main</code> et <code>develop</code>.</li><li>En cas de bug en production, une branche <code>hotfix/x.y.z+1</code> est créée à partir de <code>main</code>, corrigée et fusionnée dans <code>main</code> et <code>develop</code>.</li></ol><p><img src="https://goo-gy.github.io/static/5e2b0ac473ed6ea7282bb1188dcfea43/90823/git-flow.png" alt="git flow"></p><h3 id="_2-github-flow" tabindex="-1">2. GitHub Flow <a class="header-anchor" href="#_2-github-flow" aria-label="Permalink to &quot;2. GitHub Flow&quot;">​</a></h3><p>GitHub Flow est une approche plus simple, basée sur l&#39;intégration continue :</p><ul><li><code>main</code> : Contient toujours le code prêt pour la production.</li><li><code>feature/*</code> : Branches créées pour chaque nouvelle fonctionnalité ou correction de bug.</li></ul><p><strong>Workflow typique :</strong></p><ol><li>Création d&#39;une branche <code>feature/nom-feature</code> à partir de <code>main</code>.</li><li>Développement et commits sur cette branche.</li><li>Ouverture d&#39;une Pull Request (PR) pour examiner le code.</li><li>Une fois validée, la PR est fusionnée dans <code>main</code>.</li><li>Déploiement automatique ou manuel du code fusionné.</li></ol><h3 id="_3-trunk-based-development" tabindex="-1">3. Trunk-Based Development <a class="header-anchor" href="#_3-trunk-based-development" aria-label="Permalink to &quot;3. Trunk-Based Development&quot;">​</a></h3><p>Approche où les développeurs intègrent fréquemment leurs modifications dans une branche principale (<code>main</code> ou <code>trunk</code>). Les branches de courte durée sont privilégiées pour éviter la dérive du code.</p><p><strong>Avantages :</strong></p><ul><li>Déploiement fréquent.</li><li>Moins de complexité dans la gestion des branches.</li><li>Favorise l&#39;intégration continue.</li></ul><h2 id="bonnes-pratiques" tabindex="-1">Bonnes pratiques <a class="header-anchor" href="#bonnes-pratiques" aria-label="Permalink to &quot;Bonnes pratiques&quot;">​</a></h2><ul><li>Toujours utiliser des noms de branches clairs (<code>feature/ajout-login</code>, <code>hotfix/correction-bug-123</code>).</li><li>Effectuer des commits atomiques avec des messages explicites.</li><li>Faire des Pull Requests et demander une revue de code.</li><li>Maintenir <code>main</code> toujours stable et prêt pour la production.</li><li>Éviter les branches longues pour faciliter l&#39;intégration continue.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Adopter une stratégie de branches adaptée à votre projet permet d&#39;améliorer la collaboration et la qualité du code. Selon la taille et les besoins de votre équipe, vous pouvez opter pour <strong>Git Flow</strong> pour des cycles de développement structurés, <strong>GitHub Flow</strong> pour plus de flexibilité, ou <strong>Trunk-Based Development</strong> pour un développement rapide et agile.</p><hr><h3 id="ressources-supplementaires" tabindex="-1">Ressources supplémentaires <a class="header-anchor" href="#ressources-supplementaires" aria-label="Permalink to &quot;Ressources supplémentaires&quot;">​</a></h3><ul><li><a href="https://git-scm.com/doc" target="_blank" rel="noreferrer">Documentation officielle Git</a></li><li><a href="https://guides.github.com/introduction/flow/" target="_blank" rel="noreferrer">GitHub Flow</a></li><li><a href="https://nvie.com/posts/a-successful-git-branching-model/" target="_blank" rel="noreferrer">Présentation de Git Flow</a></li><li><a href="https://trunkbaseddevelopment.com/" target="_blank" rel="noreferrer">Trunk-Based Development</a></li></ul>',30),a=[n];function s(l,c,d,u,p,h){return o(),t("div",null,a)}const g=e(r,[["render",s]]);export{m as __pageData,g as default};
